create a helper redo function in this nuxt composable

```
import useInfoSections from "~/composables/Tenant/useInfoSections";
import {
  InfoComponent,
  InfoSection,
  InfoSubSection,
} from "~/types/Tenant/InfoPages";
import { deepClone } from "~/utils/common/objects";

export default function useActiveBlockHistory() {
  const { activeBlock, activeComponent, activeSection } = useInfoSections();

  const historyStack = useLocalStorage<
    (InfoSection | InfoSubSection | InfoComponent)[]
  >("history-stack", [], { deep: true });

  let last_snap_shot: InfoSection | InfoSubSection | InfoComponent | null =
    null;


  // keeps poping and pushing same value
  const { pause, resume } = pausableWatch(
    activeBlock,
    (prevValue) => {
      if (prevValue) {
        if (last_snap_shot) historyStack.value.push(last_snap_shot);
        last_snap_shot = deepClone(prevValue);
      }
    },
    {
      deep: true,
    },
  );

  const undoActiveBlock = async () => {
    const lastBlock = historyStack.value.pop();
    if (!lastBlock) return;

    pause();
    await nextTick();

    if (lastBlock?.block_type === "component") {
      activeComponent.value = lastBlock;
    } else if (lastBlock?.block_type === "section") {
      activeSection.value = lastBlock;
    } else if (lastBlock?.block_type === "sub-section") {
      if (activeSection.value)
        activeSection.value.sub_sections[lastBlock.id] = lastBlock;
    }

    await nextTick();
    resume();
  };

  const clearHistory = () => (historyStack.value = []);

  onMounted(() => {
    clearHistory();
  });

  return { undoActiveBlock, clearHistory };
}

``

LLM_output:
Looking at your composable, I can see you have an undo system that tracks changes to active blocks. To add a redo functionality, you'll need to maintain a separate redo stack that stores items when they're undone. Here's the updated composable with a redo function:

```typescript
import useInfoSections from "~/composables/Tenant/useInfoSections";
import {
  InfoComponent,
  InfoSection,
  InfoSubSection,
} from "~/types/Tenant/InfoPages";
import { deepClone } from "~/utils/common/objects";

export default function useActiveBlockHistory() {
  const { activeBlock, activeComponent, activeSection } = useInfoSections();

  const historyStack = useLocalStorage<
    (InfoSection | InfoSubSection | InfoComponent)[]
  >("history-stack", [], { deep: true });

  const redoStack = useLocalStorage<
    (InfoSection | InfoSubSection | InfoComponent)[]
  >("redo-stack", [], { deep: true });

  let last_snap_shot: InfoSection | InfoSubSection | InfoComponent | null =
    null;

  // Flag to prevent adding to history during undo/redo operations
  let isUndoRedoOperation = false;

  const { pause, resume } = pausableWatch(
    activeBlock,
    (prevValue) => {
      if (prevValue && !isUndoRedoOperation) {
        if (last_snap_shot) historyStack.value.push(last_snap_shot);
        last_snap_shot = deepClone(prevValue);
        // Clear redo stack when new changes are made
        redoStack.value = [];
      }
    },
    {
      deep: true,
    },
  );

  const applyBlock = async (block: InfoSection | InfoSubSection | InfoComponent) => {
    pause();
    isUndoRedoOperation = true;
    await nextTick();

    if (block?.block_type === "component") {
      activeComponent.value = block;
    } else if (block?.block_type === "section") {
      activeSection.value = block;
    } else if (block?.block_type === "sub-section") {
      if (activeSection.value)
        activeSection.value.sub_sections[block.id] = block;
    }

    await nextTick();
    isUndoRedoOperation = false;
    resume();
  };

  const undoActiveBlock = async () => {
    const lastBlock = historyStack.value.pop();
    if (!lastBlock) return;

    // Save current state to redo stack before undoing
    if (activeBlock.value) {
      redoStack.value.push(deepClone(activeBlock.value));
    }

    await applyBlock(lastBlock);
  };

  const redoActiveBlock = async () => {
    const redoBlock = redoStack.value.pop();
    if (!redoBlock) return;

    // Save current state to history stack before redoing
    if (activeBlock.value) {
      historyStack.value.push(deepClone(activeBlock.value));
    }

    await applyBlock(redoBlock);
  };

  const clearHistory = () => {
    historyStack.value = [];
    redoStack.value = [];
  };

  const canUndo = computed(() => historyStack.value.length > 0);
  const canRedo = computed(() => redoStack.value.length > 0);

  onMounted(() => {
    clearHistory();
  });

  return { 
    undoActiveBlock, 
    redoActiveBlock, 
    clearHistory,
    canUndo,
    canRedo
  };
}
```

Key changes made:

1. **Added redo stack**: A separate storage for items that have been undone.

2. **Created `applyBlock` helper**: Extracted the common logic for applying a block change to avoid duplication between undo and redo.

3. **Added `isUndoRedoOperation` flag**: Prevents the watcher from adding items to history during undo/redo operations.

4. **Modified the watcher**: Now clears the redo stack when new changes are made (standard undo/redo behavior).

5. **Updated `undoActiveBlock`**: Now saves the current state to the redo stack before undoing.

6. **Added `redoActiveBlock`**: Pops from the redo stack and applies the change, while saving the current state to the history stack.

7. **Added computed properties**: `canUndo` and `canRedo` to help with UI state management (e.g., disabling buttons when there's nothing to undo/redo).

8. **Updated `clearHistory`**: Now also clears the redo stack.

This implementation follows the standard undo/redo pattern where:
- Making a new change clears the redo stack
- Undoing moves the current state to the redo stack
- Redoing moves the current state back to the history stack

