To access the `/sdcard/` path in C++ native code on Android, you have several options:

## Option 1: Pass the path from Java to C++

The most straightforward approach is to get the path in Java and pass it to your native code:

**Java side:**
```java
String externalStoragePath = Environment.getExternalStorageDirectory().getPath();
// Pass to native method
nativeMethod(externalStoragePath);
```

**C++ side:**
```cpp
extern "C" JNIEXPORT void JNICALL
Java_com_example_app_MainActivity_nativeMethod(JNIEnv* env, jobject /* this */, jstring path) {
    const char* nativePath = env->GetStringUTFChars(path, nullptr);
    // Use the path
    std::string storagePath(nativePath);
    env->ReleaseStringUTFChars(path, nativePath);
}
```

## Option 2: Call Java method from C++

You can call the Java `Environment.getExternalStorageDirectory()` method directly from C++:

```cpp
std::string getExternalStoragePath(JNIEnv* env) {
    // Get Environment class
    jclass envClass = env->FindClass("android/os/Environment");

    // Get the getExternalStorageDirectory method ID
    jmethodID getExtStorageMethod = env->GetStaticMethodID(
        envClass, 
        "getExternalStorageDirectory", 
        "()Ljava/io/File;"
    );

    // Call getExternalStorageDirectory()
    jobject fileObject = env->CallStaticObjectMethod(envClass, getExtStorageMethod);

    // Get File class and getPath method
    jclass fileClass = env->GetObjectClass(fileObject);
    jmethodID getPathMethod = env->GetMethodID(fileClass, "getPath", "()Ljava/lang/String;");

    // Call getPath()
    jstring pathString = (jstring)env->CallObjectMethod(fileObject, getPathMethod);

    // Convert to C++ string
    const char* path = env->GetStringUTFChars(pathString, nullptr);
    std::string result(path);
    env->ReleaseStringUTFChars(pathString, path);

    // Clean up local references
    env->DeleteLocalRef(envClass);
    env->DeleteLocalRef(fileObject);
    env->DeleteLocalRef(fileClass);
    env->DeleteLocalRef(pathString);

    return result;
}
```

## Option 3: Use hardcoded path (not recommended)

While `/sdcard/` often works, it's not guaranteed across all devices:

```cpp
const char* externalStoragePath = "/sdcard/";
// Or more commonly:
const char* externalStoragePath = "/storage/emulated/0/";
```

## Important Notes:

1. **Permissions**: Make sure you have the necessary permissions in your `AndroidManifest.xml`:
   ```xml
   <uses-permission android:name="android.permission.READ_EXTERNAL_STORAGE" />
   <uses-permission android:name="android.permission.WRITE_EXTERNAL_STORAGE" />
   ```

2. **Scoped Storage**: Starting from Android 10 (API 29), access to external storage is restricted. You might need to use scoped storage APIs or request legacy storage access.

3. **Runtime Permissions**: For Android 6.0+ (API 23+), you need to request storage permissions at runtime.

The first two options are preferred as they use the proper Android APIs to get the correct path for the specific device.

```python
from flask import Flask, request, redirect, url_for, make_response, jsonify
from werkzeug.security import generate_password_hash, check_password_hash
import secrets
import datetime

app = Flask(__name__)

# In-memory storage (use a database in production)
users = {}  # {username: {password_hash, email, created_at}}
sessions = {}  # {session_id: {username, expires_at}}

SESSION_DURATION = datetime.timedelta(hours=24)

def generate_session_id():
    return secrets.token_urlsafe(32)

def is_session_valid(session_id):
    if session_id not in sessions:
        return False
    if datetime.datetime.now() > sessions[session_id]['expires_at']:
        del sessions[session_id]
        return False
    return True

@app.route('/register', methods=['GET', 'POST'])
def register():
    if request.method == 'GET':
        return '''
        <form method="POST">
            <input type="text" name="username" placeholder="Username" required><br>
            <input type="password" name="password" placeholder="Password" required><br>
            <input type="email" name="email" placeholder="Email" required><br>
            <button type="submit">Register</button>
        </form>
        '''

    username = request.form.get('username')
    password = request.form.get('password')
    email = request.form.get('email')

    if username in users:
        return 'Username already exists', 400

    users[username] = {
        'password_hash': generate_password_hash(password),
        'email': email,
        'created_at': datetime.datetime.now()
    }

    return redirect(url_for('login'))

@app.route('/login', methods=['GET', 'POST'])
def login():
    if request.method == 'GET':
        return '''
        <form method="POST">
            <input type="text" name="username" placeholder="Username" required><br>
            <input type="password" name="password" placeholder="Password" required><br>
            <button type="submit">Login</button>
        </form>
        '''

    username = request.form.get('username')
    password = request.form.get('password')

    if username not in users:
        return 'Invalid credentials', 401

    if not check_password_hash(users[username]['password_hash'], password):
        return 'Invalid credentials', 401

    # Create session
    session_id = generate_session_id()
    sessions[session_id] = {
        'username': username,
        'expires_at': datetime.datetime.now() + SESSION_DURATION
    }

    response = make_response(redirect(url_for('profile')))
    response.set_cookie('session_id', session_id, httponly=True, secure=True, samesite='Lax')
    return response

@app.route('/profile')
def profile():
    session_id = request.cookies.get('session_id')

    if not session_id or not is_session_valid(session_id):
        return redirect(url_for('login'))

    username = sessions[session_id]['username']
    user_data = users[username]

    return jsonify({
        'username': username,
        'email': user_data['email'],
        'created_at': user_data['created_at'].isoformat()
    })

@app.route('/logout', methods=['POST'])
def logout():
    session_id = request.cookies.get('session_id')

    if session_id and session_id in sessions:
        del sessions[session_id]

    response = make_response(redirect(url_for('login')))
    response.set_cookie('session_id', '', expires=0)
    return response

if __name__ == '__main__':
    app.run(debug=True)
```

