For a more robust solution that also checks for .m3u8 files explicitly:

```javascript
const isHLSStream = (src) => {
  return /\.m3u8$/i.test(src) || src.includes('.m3u8?');
};

const loadVideo = (src, videoElement) => {
  if (!isHLSStream(src)) {
    // Regular video file
    videoElement.src = src;
  } else if (videoElement.canPlayType("application/vnd.apple.mpegurl")) {
    // Safari native HLS
    videoElement.src = src;
  } else if (Hls.isSupported()) {
    // HLS.js for other browsers
    const hls = new Hls();
    hls.loadSource(src);
    hls.attachMedia(videoElement);
  } else {
