private byte[] GenerateSound(int soundIndex, double durationSeconds, int sampleRate = 44100)
{
    int samples = (int)(sampleRate * durationSeconds);
    byte[] buffer = new byte[samples * 2]; // 16-bit audio
    double amplitude = 0.25 * short.MaxValue * (volumeTrackBar.Value / 100.0); // Volume control

    for (int i = 0; i < samples; i++)
    {
        double t = (double)i / sampleRate;
        short sample = 0;

        switch (soundIndex)
        {
            case 0: // Bip classique 440Hz
                sample = (short)(amplitude * Math.Sin(2 * Math.PI * 440 * t));
                break;

            case 1: // Bip aigu 880Hz
                sample = (short)(amplitude * Math.Sin(2 * Math.PI * 880 * t));
                break;

            case 2: // Bip grave 220Hz
                sample = (short)(amplitude * Math.Sin(2 * Math.PI * 220 * t));
                break;

            case 3: // Double bip alternant entre 440Hz et 880Hz
                double freq = (i / (sampleRate / 4)) % 2 == 0 ? 440 : 880;
                sample = (short)(amplitude * Math.Sin(2 * Math.PI * freq * t));
                break;

            case 4: // Alarme montante (sweep de 200Hz à 800Hz)
                double sweepFreq = 200 + (600 * (t % 3) / 3); // Répète le sweep toutes les 3 secondes
                sample = (short)(amplitude * Math.Sin(2 * Math.PI * sweepFreq * t));
                break;

            case 5: // Alarme sirène (oscillation entre 600Hz et 800Hz)
                double modulation = Math.Sin(2 * Math.PI * 4 * t); // 4Hz modulation
                double sireneFreq = 700 + 100 * modulation;
                sample = (short)(amplitude * Math.Sin(2 * Math.PI * sireneFreq * t));
                break;
        }

        // Fade in/out pour éviter les clics
        if (i < sampleRate / 100) // Fade in sur 10ms
        {
            sample = (short)(sample * i / (sampleRate / 100));
        }
        else if (i > samples - sampleRate / 100) // Fade out sur 10ms
        {
            sample = (short)(sample * (samples - i) / (sampleRate / 100));
        }

        // Convertir en bytes (little-endian)
        buffer[i * 2] = (byte)(sample & 0xFF);
        buffer[i * 2 + 1] = (byte)(sample >> 8);
    }

    // Créer le fichier WAV complet
    using (MemoryStream ms = new MemoryStream())
    {
        BinaryWriter writer = new BinaryWriter(ms);

        // RIFF header
        writer.Write("RIFF".ToCharArray());
        writer.Write(36 + buffer.Length);
        writer.Write("WAVE".ToCharArray());

        // fmt chunk
        writer.Write("fmt ".ToCharArray());
        writer.Write(16); // Chunk size
        writer.Write((short)1); // PCM
        writer.Write((short)1); // Mono
        writer.Write(sampleRate);
        writer.Write(sampleRate * 2); // Byte rate
        writer.Write((short)2); // Block align
        writer.Write((short)16); // Bits per sample

        // data chunk
        writer.Write("data".ToCharArray());
        writer.Write(buffer.Length);
        writer.Write(buffer);

        return ms.ToArray();
    }
}

private void QuickButton_Click(object sender, EventArgs e)
{
    Button btn = sender as Button;
    if (btn != null)
    {
        SetTimeAndStart((int)btn.Tag);
    }
}

private void SetButton_Click(object sender, EventArgs e)
{
    int totalSeconds = (int)hoursInput.Value * 3600 + (int)minutesInput.Value * 60 + (int)secondsInput.Value;
    SetTimeAndStart(totalSeconds);
}

private void SetTimeAndStart(int totalSeconds)
{
    if (totalSeconds <= 0)
    {
        MessageBox.Show("Veuillez entrer un temps positif.", "Temps invalide", MessageBoxButtons.OK, MessageBoxIcon.Warning);
        return;
    }
    StopAndResetTimer();
    remainingSeconds = totalSeconds;
    UpdateTimeDisplay();
    StartTimer();
}

private void StartStopButton_Click(object sender, EventArgs e)
{
    if (isTimerRunning)
    {
        StopTimer();
    }
    else
    {
        if (remainingSeconds == 0)
        {
            int totalSeconds = (int)hoursInput.Value * 3600 + (int)minutesInput.Value * 60 + (int)secondsInput.Value;
            if (totalSeconds <= 0)
            {
                MessageBox.Show("Veuillez définir un temps avant de démarrer.", "Info", MessageBoxButtons.OK, MessageBoxIcon.Information);
                return;
            }
            remainingSeconds = totalSeconds;
            UpdateTimeDisplay();
        }
        StartTimer();
    }
}

private void StartTimer()
{
    if (remainingSeconds > 0 && !isTimerRunning)
    {
        isTimerRunning = true;
        countdownTimer.Start();
        startStopButton.Text = "Arrêter";
        startStopButton.BackColor = Color.LightCoral;
    }
}

private void StopTimer()
{
    isTimerRunning = false;
    countdownTimer.Stop();
    startStopButton.Text = "Démarrer";
    startStopButton.BackColor = Color.LightGreen;
    alarmPlayer.Stop();
}

private void StopAndResetTimer()
{
    StopTimer();
    remainingSeconds = 0;
    UpdateTimeDisplay();
    timeLabel.ForeColor = Color.DarkBlue;
}

private void CountdownTimer_Tick(object sender, EventArgs e)
{
    if (remainingSeconds > 0)
    {
        remainingSeconds--;
        UpdateTimeDisplay();

        // Changer la couleur quand il reste peu de temps
        if (remainingSeconds <= 10)
        {
            timeLabel.ForeColor = Color.Red;
        }
        else if (remainingSeconds <= 30)
        {
            timeLabel.ForeColor = Color.Orange;
        }
    }
    else
    {
        StopTimer();
        UpdateTimeDisplay();
        PlayAlarm();

        // Flash de la fenêtre
        this.WindowState = FormWindowState.Normal;
        this.Activate();
        this.BringToFront();

        MessageBox.Show("Temps écoulé !", "Cook Timer", MessageBoxButtons.OK, MessageBoxIcon.Information);
    }
}

private void UpdateTimeDisplay()
{
    TimeSpan ts = TimeSpan.FromSeconds(remainingSeconds);
    timeLabel.Text = string.Format("{0:D2}:{1:D2}:{2:D2}", ts.Hours, ts.Minutes, ts.Seconds);
}

private void PlayAlarm()
{
    try
    {
        int selectedSound = soundComboBox.SelectedIndex;
        if (selectedSound >= 0 && selectedSound < soundNames.Length)
        {
            // Générer un son de 10 secondes qui se répète en boucle
            byte[] soundBytes = GenerateSound(selectedSound, 10.0);
            using (MemoryStream ms = new MemoryStream(soundBytes))
            {
                alarmPlayer.Stream = ms;
                alarmPlayer.PlayLooping();
            }
        }
    }
    catch (Exception ex)
    {
        MessageBox.Show("Erreur lecture son: " + ex.Message);
    }
}

private void PlaySound(double duration)
{
    try
    {
        int selectedSound = soundComboBox.SelectedIndex;
        if (selectedSound >= 0 && selectedSound < soundNames.Length)
        {
            byte[] soundBytes = GenerateSound(selectedSound, duration);
            using (MemoryStream ms = new MemoryStream(soundBytes))
            {
                alarmPlayer.Stream = ms;
                alarmPlayer.Play();
            }
        }
    }
    catch (Exception ex)
    {
        MessageBox.Show("Erreur lecture son: " + ex.Message);
    }
}

// --- Tray Icon Logic ---
private NotifyIcon trayIcon;
private ContextMenuStrip trayMenu;

private void SetupTrayIcon()
{
    trayMenu = new ContextMenuStrip();
    trayMenu.Items.Add("Restaurer", null, OnRestoreFromTray);
    trayMenu.Items.Add("Quitter", null, OnQuitFromTray);

    trayIcon = new NotifyIcon()
    {
        Icon = SystemIcons.Application,
        ContextMenuStrip = trayMenu,
        Visible = false,
        Text = "Cook Timer"
    };
    trayIcon.DoubleClick += OnRestoreFromTray;

    try
    {
        this.Icon = new Icon("app_icon.ico");
        trayIcon.Icon = new Icon("app_icon.ico");
    }
    catch { /* Gérer si l'icône n'est pas trouvée */ }
}

private void CookTimerForm_Resize(object sender, EventArgs e)
{
    if (this.WindowState == FormWindowState.Minimized)
    {
        if (trayIcon == null) SetupTrayIcon();
        trayIcon.Visible = true;
        this.ShowInTaskbar = false;
    }
}

private void OnRestoreFromTray(object sender, EventArgs e)
{
    this.WindowState = FormWindowState.Normal;
    this.ShowInTaskbar = true;
    if (trayIcon != null) trayIcon.Visible = false;
    this.Activate();
}

private void OnQuitFromTray(object sender, EventArgs e)
{
    Application.Exit();
}

protected override void OnFormClosing(FormClosingEventArgs e)
{
    if (trayIcon != null)
    {
        trayIcon.Visible = false;
        trayIcon.Dispose();
    }
    base.OnFormClosing(e);
}

[STAThread]
public static void Main()
{
    Application.EnableVisualStyles();
    Application.SetCompatibleTextRenderingDefault(false);
    Application.Run(new CookTimerForm());
}
}

