LLM_output:
To make the clipboard content **monospaced**, you need to preserve the font formatting. However, the `clipboard.writeText()` method only lets you copy plain text — it cannot control how the pasted content is displayed (like using monospace). For rich text (e.g., HTML or styled), you must use `navigator.clipboard.write()` with a `ClipboardItem`.

Here’s how you can modify your function to support copying as **monospace** by writing HTML content when `isMonospace` is `true`:

```ts
const copyTextToClipboard = async (
  text: string,
  type: string,
  isMonospace: boolean = false
) => {
  try {
    if (!navigator.clipboard) {
      throw new Error("Clipboard API not supported");
    }

    if (isMonospace && navigator.clipboard.write) {
      const html = `<pre style="font-family: monospace;">${escapeHtml(text)}</pre>`;
      const blob = new Blob([html], { type: "text/html" });
      const item = new ClipboardItem({ "text/html": blob });
      await navigator.clipboard.write([item]);
    } else {
      await navigator.clipboard.writeText(text);
    }

    notify.success(`${type} text copied to clipboard!`);
  } catch (err) {
    console.error(`Failed to copy ${type} text: `, err);
    notify.error(`Failed to copy ${type} text to clipboard`);
  }
};

// Helper to escape HTML characters
const escapeHtml = (text: string): string =>
  text.replace(/[&<>"']/g, (char) => {
    const escapeMap: { [key: string]: string } = {
      "&": "&amp;",
      "<": "&lt;",
      ">": "&gt;",
      '"': "&quot;",
      "'": "&#39;",
    };
    return escapeMap[char] || char;
  });
```

### 🔍 Explanation:
- **Monospace Trick**: A `<pre>` tag with CSS `font-family: monospace` will render the copied content with monospace font if pasted into a rich-text editor (e.g., Gmail, Word, etc.).
- **Plain Text Fallback**: If `isMonospace` is `false`, it just copies regular text.
- **HTML Escaping**: Prevents HTML injection when copying code.

> ✅ Note: Rich HTML copying only works in contexts that support the `ClipboardItem` API (modern browsers) and may not behave as expected when pasted into plain-text editors (e.g., Notepad).

Creating **animated noise** using **OpenCL** involves writing an OpenCL kernel that generates noise (such as Perlin or simple value noise) and updates over time. You'll also need some host code (in C or C++) to interact with the OpenCL device and update the animation over frames.

Here’s a simple example generating **animated 2D value noise** using OpenCL. This implementation assumes you're familiar with OpenCL setup basics (platform, device, context, command queue, etc.).

---

## 🎯 Key Elements:
- **Noise function**: Simple value noise (not Perlin/Simplex, which are more complex).
- **Time-based update**: A time or frame offset is added to animate the noise.
- **2D image output**: Each pixel in an image is a noise value.

---

### 🔧 OpenCL Kernel (`noise.cl`):

```c
__constant int permutation[] = {
    151,160,137,91,90,15, // permutation table for pseudo randomness
    // Repeat the array (total 512 entries)
    151,160,137,91,90,15, // You can fill rest or use a lookup function
};

float fade(float t) {
    return t * t * t * (t * (t * 6 - 15) + 10);
}

float lerp(float a, float b, float t) {
    return a + t * (b - a);
}

float grad(int hash, float x, float y) {
    // Convert lower 4 bits of hash into a gradient direction
    int h = hash & 7;
    float u = h<4 ? x : y;
    float v = h<4 ? y : x;
    return ((h&1) ? -u : u) + ((h&2) ? -v : v);
}

float noise(float x, float y) {
    int X = (int)floor(x) & 255;
    int Y = (int)floor(y) & 255;
    x -= floor(x);
    y -= floor(y);
    float u = fade(x);
    float v = fade(y);
    int A = (permutation[X] + Y) & 255;
    int B = (permutation[X + 1] + Y) & 255;

    return lerp(
        lerp(grad(permutation[A], x, y), grad(permutation[B], x - 1, y), u),
        lerp(grad(permutation[A + 1], x, y - 1), grad(permutation[B + 1], x - 1, y - 1), u),
        v);
}

__kernel void generate_noise(__global uchar* output, int width, int height, float time) {
    int x = get_global_id(0);
    int y = get_global_id(1);

    if (x >= width || y >= height)
        return;

    float scale = 0.05f;
    float fx = x * scale;
    float fy = y * scale;
    float value = noise(fx + time, fy + time); // Animate via time offset

    value = (value + 1.0f) * 0.5f; // Normalize to [0, 1]
    uchar pixel_value = (uchar)(value * 255.0f);

    int index = y * width + x;
    output[index] = pixel_value;
}
```

---

### 🤖 Host Code (C++):

```cpp
#include <CL/cl.h>
#include <iostream>
#include <vector>
#include <fstream>
#include <cmath>

#define WIDTH 512
#define HEIGHT 512

// Utility to read kernel source
std::string loadKernel(const char* filename) {
    std::ifstream stream(filename);
    return std::string(std::istreambuf_iterator<char>(stream), {});
}

int main() {
    // [1] OpenCL boilerplate: Platform, device, context, queue
    cl_platform_id platform_id;
    cl_device_id device_id;
    cl_context context;
    cl_command_queue queue;
    cl_program program;
    cl_kernel kernel;

    clGetPlatformIDs(1, &platform_id, nullptr);
    clGetDeviceIDs(platform_id, CL_DEVICE_TYPE_GPU, 1, &device_id, nullptr);
    context = clCreateContext(nullptr, 1, &device_id, nullptr, nullptr, nullptr);
    queue = clCreateCommandQueue(context, device_id, 0, nullptr);

    // [2] Load and compile kernel
    std::string source = loadKernel("noise.cl");
    const char* src = source.c_str();
    size_t src_size = source.size();
    program = clCreateProgramWithSource(context, 1, &src, &src_size, nullptr);
    clBuildProgram(program, 1, &device_id, nullptr, nullptr, nullptr);
    kernel = clCreateKernel(program, "generate_noise", nullptr);

    // [3] Create buffer
    size_t buffer_size = WIDTH * HEIGHT * sizeof(unsigned char);
    cl_mem output_buffer = clCreateBuffer(context, CL_MEM_WRITE_ONLY, buffer_size, nullptr, nullptr);
    std::vector<unsigned char> output(WIDTH * HEIGHT);

    // [4] Animation loop (simulate updating over time)
    for (float t = 0; t < 10.0f; t += 0.1f) {
        // Set kernel args
        clSetKernelArg(kernel, 0, sizeof(cl_mem), &output_buffer);
        clSetKernelArg(kernel, 1, sizeof(int), &WIDTH);
        clSetKernelArg(kernel, 2, sizeof(int), &HEIGHT);
        clSetKernelArg(kernel, 3, sizeof(float), &t); // time

        // Run kernel
        size_t global[2] = { WIDTH, HEIGHT };
        clEnqueueNDRangeKernel(queue, kernel, 2, nullptr, global, nullptr, 0, nullptr, nullptr);

        // Read back
        clEnqueueReadBuffer(queue, output_buffer, CL_TRUE, 0, buffer_size, output.data(), 0, nullptr, nullptr);

        // Save or display output per frame (for simplicity, write to .pgm image)
        char filename[32];
        sprintf(filename, "frame_%03d.pgm", (int)(t * 10));
        std::ofstream img(filename, std::ios::binary);
        img << "P5\n" << WIDTH << " " << HEIGHT << "\n255\n";
        img.write((char*)output.data(), output.size());
        img.close();

        std::cout << "Generated frame at t=" << t << std::endl;
    }

    // Cleanup
    clReleaseMemObject(output_buffer);
    clReleaseKernel(kernel);
    clReleaseProgram(program);
    clReleaseCommandQueue(queue);
    clReleaseContext(context);
    return 0;
}
```

---

### 📼 Output
You'll get a sequence of `.pgm` images representing animated noise. You can combine them into a video using `ffmpeg`:

```bash
ffmpeg -framerate 30 -i frame_%03d.pgm -c:v libx264 -pix_fmt yuv420p noise_animation.mp4
```

---

## 🧠 Notes
- For better visual quality, implement **Perlin**, **Worley**, or **Simplex** noise.
- You can optimize this further using image2D output instead of linear buffers.
- Try adding `octaves` and `persistence` for **fractal noise**.

Would you like a more advanced version with OpenCL image outputs or Simplex noise?

