### Way #1: **Best (Structured, Scalable, Maintainable)**

```java
import java.util.*;

class NPC {
    int id;

    NPC(int id) {
        this.id = id;
    }

    boolean isAlive() {
        // Assume this method exists and returns the actual alive status
        return true;
    }
}

class Faction {
    int id;
    Set<Integer> npcIds = new HashSet<>();

    Faction(int id) {
        this.id = id;
    }

    void addNpc(int npcId) {
        npcIds.add(npcId);
    }

    boolean containsNpc(int npcId) {
        return npcIds.contains(npcId);
    }
}

class NPCManager {
    Map<Integer, NPC> npcs = new HashMap<>();
    Map<Integer, Faction> factions = new HashMap<>();
    Map<Integer, List<Integer>> linkNpcMap = new HashMap<>();

    void registerNPC(NPC npc) {
        npcs.put(npc.id, npc);
    }

    void registerFaction(Faction faction) {
        factions.put(faction.id, faction);
    }

    void linkNPCs(int newNpcId, List<Integer> relatedNpcIds) {
        linkNpcMap.put(newNpcId, relatedNpcIds);
    }

    boolean canAttack(int playerFactionId, int npcId) {
        if (!linkNpcMap.containsKey(npcId)) return true;

        List<Integer> related = linkNpcMap.get(npcId);
        for (int relatedId : related) {
            NPC relatedNpc = npcs.get(relatedId);
            if (relatedNpc != null && factions.get(playerFactionId).containsNpc(relatedId) && relatedNpc.isAlive()) {
                return false;
            }
        }
        return true;
    }
}
```

