Map<Integer, List<Integer>> links = new HashMap<>();

boolean canAttack(int playerFactionId, int npcId) {
    List<Integer> tied = links.get(npcId);
    if (tied == null) return true;

    for (int id : tied) {
        if (id / 100 == playerFactionId && isAlive(id)) return false;
    }
    return true;
}

boolean isAlive(int npcId) {
    return true;
}
```

