                                          color: theme.colorScheme.primary,
                                          decoration: TextDecoration.underline,
                                        ),
                                      ),
                                    ),
                                  ),
                              ],
                            ),
                            isActive: _currentStep == 1,
                            state: _steamCmdPath != null &&
                                    _isSteamCmdExist(_steamCmdPath)
                                ? StepState.complete
                                : StepState.indexed,
                          ),
                          Step(
                            title: const Text('安装汉化包'),
                            content: InstallSection(
                              isInstalling: _isInstalling,
                              downloadProgress: _downloadProgress,
                              onInstall: _downloadAndInstall,
                              isInstallEnabled:
                                  _gamePath != null && _steamCmdPath != null,
                            ),
                            isActive: _currentStep == 2,
                            state: _isInstalling
                                ? StepState.editing
                                : (_gamePath != null && _steamCmdPath != null
                                    ? StepState.indexed
                                    : StepState.disabled),
                          ),
                        ],
                      ),
                    ],
                  ),
                ),
              ),
            ),
          ),
        );
      },
    ),
  );
}
```

---

### 🔍 解读这个修改：
- `LayoutBuilder`：获取父容器（通常是屏幕）的最大高度。
- `ConstrainedBox(BoxConstraints(minHeight: constraints.maxHeight))`：确保卡片内容**最少填满屏幕高度**。
- `SingleChildScrollView`：在内容超出时能滚动。
- `Center(...)`：保持居中。

这样，**当窗口拉高时内容也会拉高；不拉高时才滚动**，整体体验更「自适应」。

---

### ✅ 补充建议
- 如果希望宽度在较大屏幕下不要太宽，还可以用 `SizedBox(width: 600, child: Card(...))` 控制最大宽度。
- `Stepper` 组件在窗口大小变化时可能也会影响布局，适当地测试响应式布局效果很重要。

---

