      margin-bottom: 20px;
      font-size: 18px;
      color: #333;
    }
    .component {
      margin-bottom: 10px;
      padding: 10px;
      background: #fff;
      border: 1px solid #ddd;
      display: flex;
      align-items: center;
    }
    .shape {
      width: 40px;
      height: 40px;
      margin-right: 15px;
    }
    .beans { background: brown; border-radius: 50%; }
    .grinder { background: gray; }
    .machine { background: black; }
    .mug { background: lightblue; border-radius: 0 10px 10px 0; position: relative; }
    .milk { background: white; border-radius: 50%; }
    button {
      margin-left: auto;
      padding: 5px 10px;
    }
  </style>
</head>
<body>

  <h1>Coffee-Making Simulator</h1>
  <div id="instructions">Step 1: Add beans.</div>

  <div class="component">
    <div class="shape beans"></div>
    <span>Beans</span>
    <button id="grindButton" disabled>Grind Beans</button>
  </div>

  <div class="component">
    <div class="shape grinder"></div>
    <span>Grinder</span>
    <button id="brewButton" disabled>Brew Coffee</button>
  </div>

  <div class="component">
    <div class="shape machine"></div>
    <span>Coffee Machine</span>
    <button id="pourButton" disabled>Pour into Mug</button>
  </div>

  <div class="component">
    <div class="shape mug"></div>
    <span>Mug</span>
    <button id="milkButton" disabled>Add Milk</button>
  </div>

  <div class="component">
    <div class="shape milk"></div>
    <span>Milk</span>
  </div>

  <div style="margin-top: 20px;">
    <button onclick="reset()">Reset</button>
  </div>

  <script>
    // Step handling
    let currentStep = 0;

    // Button references
    const grindButton = document.getElementById('grindButton');
    const brewButton = document.getElementById('brewButton');
    const pourButton = document.getElementById('pourButton');
    const milkButton = document.getElementById('milkButton');
    const instructions = document.getElementById('instructions');

    // Step descriptions
    const steps = [
      "Step 1: Add beans.",
      "Step 2: Grind the beans.",
      "Step 3: Brew the coffee.",
      "Step 4: Pour into the mug.",
      "Step 5: Add milk (optional).",
      "Coffee is ready! ☕"
    ];

    function updateInstructions() {
      instructions.textContent = steps[currentStep] || "Done!";
    }

    function updateUI() {
      grindButton.disabled = currentStep !== 1;
      brewButton.disabled = currentStep !== 2;
      pourButton.disabled = currentStep !== 3;
      milkButton.disabled = currentStep !== 4;
      updateInstructions();
    }

    // Component actions
    function proceedTo(nextStep) {
      currentStep = nextStep;
      updateUI();
    }

    grindButton.onclick = () => {
      if (currentStep === 1) proceedTo(2);
    };

    brewButton.onclick = () => {
      if (currentStep === 2) proceedTo(3);
    };

    pourButton.onclick = () => {
      if (currentStep === 3) proceedTo(4);
    };

    milkButton.onclick = () => {
      if (currentStep === 4) proceedTo(5);
    };

    function reset() {
      currentStep = 1;
      updateUI();
    }

    // Initialize simulation
    window.onload = reset;
  </script>

</body>
</html>
```

