const myGauge = new Gauge({
  name: "Temperature",
  description: "Room Temperature Monitor",
  unit: "°C",
  range: [0, 100],
  step: 0.5,
  precision: 1,
  value: 37.2,
  ticks: 6,
  brackets: [
    { min: 0, max: 25, color: "red", label: "Cold" },
    { min: 26, max: 50, color: "yellow", label: "Warm" },
    { min: 51, max: 75, color: "blue", label: "Hot" },
    { min: 76, max: 100, color: "green", label: "Very Hot" }
  ]
});

console.log(myGauge.toString());
myGauge.drawGaugeImage('temperature_gauge.png');

